\begin{proposition}\label{thm1v2}
    Let $\DD$ be $\beta$-max-concentrating and $v\in \RR$. Let $\mu \in M(\DD, C)$. Then
    \begin{equation}
        \int_{v_S}^\infty p_\mu(v)\,d\eta(v) = O\left(C^{-K(\beta,\gamma)}\right),
    \end{equation}
    where
    \begin{equation}
        K(\beta,\gamma) := \frac{2\beta\gamma}{3\beta\gamma + 2\beta + 5\gamma + 6}.
    \end{equation}
\end{proposition}

\begin{proposition}\label{thm2v2}
Let $\DD$ be long-tailed. Then, for all $C$ sufficiently large, for all $\epsilon>0$ and any $\mu\in M(\DD, C)$,
\begin{equation}
    \Pr[\mu(v)\in C]\in (S-\epsilon, S+\epsilon).
\end{equation}
for all $v\in (v_\epsilon^-, v_\epsilon^+)$ for $v_\epsilon^-, v_\epsilon^+$ chosen such that $\eta(-\infty, v_\epsilon^-) = \eta((v_\epsilon, \infty)) = \epsilon$.
\end{proposition}

\begin{proposition}\label{prop:tomato}
\quad
    \begin{itemize}
